.up p{margin:0}
.up__r{color:#525252}
.up__b{display:inline-flex;align-items:center;min-height:44px;padding:0 20px;border:1px solid #0a0a0a;border-radius:999px;background:#0a0a0a;color:#fff;font-weight:600;cursor:pointer}
/* interaction */
.up__b{position:relative}.up__b input{position:absolute;inset:0;width:100%;opacity:0;cursor:pointer}.up__b:focus-within{outline:2px solid #1d4ed8;outline-offset:2px}.up__list{list-style:none;margin:0;padding:0;font-size:13px;text-align:left}.up__list li{padding:2px 0}.up__list .is-bad{color:#b91c1c}

code.js:
document.querySelectorAll('.up').forEach(zone => {
  const input = zone.querySelector('input[type=file]'), list = zone.querySelector('.up__list');
  const MAX = 10 * 1024 * 1024, OK = ['application/pdf', 'image/png'];
  const show = files => {
    list.innerHTML = '';
    [...files].forEach(f => {
      const li = document.createElement('li'), bad = !OK.includes(f.type) ? 'is not a PDF or PNG' : f.size > MAX ? 'is over 10 MB' : '';
      li.textContent = bad ? f.name + ' ' + bad : f.name + ' (' + Math.max(1, Math.round(f.size / 1024)) + ' KB)';
      if (bad) li.className = 'is-bad'; list.appendChild(li);
    });
  };
  input.addEventListener('change', () => show(input.files));
  ['dragenter', 'dragover'].forEach(t => zone.addEventListener(t, e => { e.preventDefault(); zone.classList.add('is-over'); }));
  ['dragleave', 'drop'].forEach(t => zone.addEventListener(t, e => { e.preventDefault(); zone.classList.remove('is-over'); }));
  zone.addEventListener('drop', e => show(e.dataTransfer.files));
});
